"""Incremental DAG execution backed by a shared JSON cache."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Mapping

from .model import BuildResult, Compiler, PipelineError, default_compiler
from .store import CacheStore


class Pipeline:
    def __init__(self, cache_file: str | Path, compiler: Compiler | None = None):
        self.store = CacheStore(cache_file)
        self.compiler = compiler or default_compiler

    @staticmethod
    def _source_stamp(path: Path) -> dict[str, int]:
        metadata = path.stat()
        return {"mtime_ns": metadata.st_mtime_ns, "size": metadata.st_size}

    @staticmethod
    def _load_manifest(root: Path) -> dict[str, dict[str, object]]:
        try:
            raw = json.loads((root / "pipeline.json").read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            raise PipelineError("pipeline.json is unreadable") from exc
        nodes = raw.get("nodes") if isinstance(raw, dict) else None
        if not isinstance(nodes, dict) or not nodes:
            raise PipelineError("pipeline.json must declare nodes")
        normalized: dict[str, dict[str, object]] = {}
        for name, declaration in nodes.items():
            if not isinstance(name, str) or not name or not isinstance(declaration, dict):
                raise PipelineError("invalid node declaration")
            source = declaration.get("source")
            dependencies = declaration.get("dependencies", [])
            if (
                not isinstance(source, str)
                or not source
                or not isinstance(dependencies, list)
                or any(not isinstance(item, str) or not item for item in dependencies)
            ):
                raise PipelineError(f"invalid declaration for {name}")
            normalized[name] = {
                "source": source,
                "dependencies": list(dependencies),
            }
        for name, declaration in normalized.items():
            unknown = [
                dependency
                for dependency in declaration["dependencies"]
                if dependency not in normalized
            ]
            if unknown:
                raise PipelineError(f"unknown dependencies for {name}: {unknown}")
        return normalized

    def build(
        self, project_root: str | Path, targets: list[str] | tuple[str, ...]
    ) -> BuildResult:
        root = Path(project_root).resolve(strict=True)
        nodes = self._load_manifest(root)
        if not targets or any(target not in nodes for target in targets):
            raise PipelineError("targets must name declared nodes")

        with self.store.transaction() as cache:
            cache_nodes = cache["nodes"]
            assert isinstance(cache_nodes, dict)
            outputs: dict[str, str] = {}
            built: list[str] = []
            reused: list[str] = []
            visiting: set[str] = set()

            def build_node(name: str) -> str:
                if name in outputs:
                    return outputs[name]
                if name in visiting:
                    raise PipelineError(f"dependency cycle includes {name}")
                visiting.add(name)
                declaration = nodes[name]
                dependencies = list(declaration["dependencies"])
                dependency_outputs = {
                    dependency: build_node(dependency) for dependency in dependencies
                }
                source_path = root / str(declaration["source"])
                try:
                    source = source_path.read_text(encoding="utf-8")
                    source_stamp = self._source_stamp(source_path)
                except OSError as exc:
                    raise PipelineError(f"cannot read source for {name}") from exc

                prior = cache_nodes.get(name)
                if (
                    isinstance(prior, dict)
                    and prior.get("source_stamp") == source_stamp
                    and prior.get("dependencies") == dependencies
                    and isinstance(prior.get("output"), str)
                ):
                    output = str(prior["output"])
                    reused.append(name)
                else:
                    output = self.compiler(name, source, dependency_outputs)
                    if not isinstance(output, str):
                        raise PipelineError("compiler must return a string")
                    cache_nodes[name] = {
                        "source_stamp": source_stamp,
                        "dependencies": dependencies,
                        "output": output,
                    }
                    built.append(name)
                outputs[name] = output
                visiting.remove(name)
                return output

            requested = {target: build_node(target) for target in targets}
            return BuildResult(
                outputs=requested,
                built=tuple(built),
                reused=tuple(reused),
            )

