"""JSON cache persistence used by :mod:`buildpipe.engine`."""

from __future__ import annotations

import json
from contextlib import contextmanager
from pathlib import Path
from typing import Iterator

from .model import PipelineError


class CacheStore:
    def __init__(self, path: str | Path):
        self.path = Path(path)

    def _load(self) -> dict[str, object]:
        if not self.path.exists():
            return {"version": 1, "nodes": {}}
        try:
            value = json.loads(self.path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            raise PipelineError("cache is unreadable") from exc
        if (
            not isinstance(value, dict)
            or value.get("version") != 1
            or not isinstance(value.get("nodes"), dict)
        ):
            raise PipelineError("cache has an unsupported shape")
        return value

    def _save(self, value: dict[str, object]) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.path.write_text(
            json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")),
            encoding="utf-8",
        )

    @contextmanager
    def transaction(self) -> Iterator[dict[str, object]]:
        """Yield the cache state used by one pipeline build."""

        value = self._load()
        try:
            yield value
        finally:
            self._save(value)
